namespace sv_1e3d25e8da214d6e9518c60db337532c.Models;

public sealed class Recipe
{
    public required int Id { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public required int PrepTimeMinutes { get; init; }
}

using sv_1e3d25e8da214d6e9518c60db337532c.Models;

namespace sv_1e3d25e8da214d6e9518c60db337532c.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomatoes.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Description = "Traditional Roman pasta with guanciale, egg yolk, Pecorino Romano, and black pepper.", PrepTimeMinutes = 25 },
            new() { Id = 3, Title = "Risotto alla Milanese", Description = "Creamy saffron-infused risotto from Milan, finished with Parmigiano-Reggiano.", PrepTimeMinutes = 40 },
        },
        [2] = new List<Recipe>
        {
            new() { Id = 4, Title = "Pad Thai", Description = "Stir-fried rice noodles with shrimp, tofu, peanuts, bean sprouts, and tamarind sauce.", PrepTimeMinutes = 20 },
            new() { Id = 5, Title = "Green Curry", Description = "Aromatic coconut milk curry with green chili paste, Thai basil, and seasonal vegetables.", PrepTimeMinutes = 35 },
            new() { Id = 6, Title = "Tom Yum Soup", Description = "Hot and sour soup with lemongrass, galangal, kaffir lime leaves, and prawns.", PrepTimeMinutes = 25 },
        },
        [3] = new List<Recipe>
        {
            new() { Id = 7, Title = "Tacos al Pastor", Description = "Marinated pork tacos with pineapple, cilantro, and onion on corn tortillas.", PrepTimeMinutes = 45 },
            new() { Id = 8, Title = "Guacamole", Description = "Fresh avocado dip with lime juice, cilantro, jalapeño, tomato, and onion.", PrepTimeMinutes = 10 },
            new() { Id = 9, Title = "Chicken Enchiladas", Description = "Corn tortillas filled with shredded chicken, topped with red chile sauce and cheese.", PrepTimeMinutes = 50 },
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes — Cuisine @CuisineId</h1>

@if (_sort is not null)
{
    <p><em>Sorted by: @_sort</em></p>
}

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    @foreach (var recipe in DisplayRecipes)
    {
        <div class="card mb-3">
            <div class="card-body">
                <h5 class="card-title">@recipe.Title</h5>
                <p class="card-text">@recipe.Description</p>
                <span class="badge bg-secondary">Prep: @recipe.PrepTimeMinutes min</span>
            </div>
        </div>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _sort;
    private string? _error;
    private bool _isRefreshing;
    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;

    private IReadOnlyList<Recipe> DisplayRecipes =>
        _sort?.Equals("popular", StringComparison.OrdinalIgnoreCase) == true
            ? _recipes!.OrderByDescending(r => r.Id).ToList()
            : _sort?.Equals("newest", StringComparison.OrdinalIgnoreCase) == true
                ? _recipes!.OrderBy(r => r.Id).ToList()
                : _recipes!;

    protected override async Task OnParametersSetAsync()
    {
        _sort = Sort;

        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            // Only the sort changed — no reload needed.
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request for a previous cuisine.
        await CancelPendingRequestAsync();

        _error = null;

        if (_recipes is not null)
        {
            _isRefreshing = true;
        }

        var cts = new CancellationTokenSource();
        _cts = cts;

        try
        {
            var data = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);
            _recipes = data;
            _loadedCuisineId = CuisineId;
        }
        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
        {
            // Request was intentionally cancelled — do nothing.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _error = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

